parameters.jsCode:
// Recibimos los datos que se guardaron en la hoja de Google
const sheetData = $('Append row in sheet').first().json;
const initialImageUrl = $('Get URL').first().json.data.url;

const tasks = [];

// Tarea para el Video 1
tasks.push({
  json: {
    video_index: 1, // Un identificador para saber qué video es
    prompt: sheetData['Transicion 1'],
    image_url: initialImageUrl,
    end_image_url: sheetData['Imagen 1']
  }
});

// Tarea para el Video 2
tasks.push({
  json: {
    video_index: 2,
    prompt: sheetData['Transicion 2'],
    image_url: sheetData['Imagen 1'],
    end_image_url: sheetData['Imagen 2']
  }
});

// Tarea para el Video 3
tasks.push({
  json: {
    video_index: 3,
    prompt: sheetData['Transicion 3'],
    image_url: sheetData['Imagen 2'],
    end_image_url: sheetData['Imagen 3']
  }
});

// Tarea para el Video 4
tasks.push({
  json: {
    video_index: 4,
    prompt: sheetData['Transicion 4'],
    image_url: sheetData['Imagen 3'],
    end_image_url: initialImageUrl
  }
});

return tasks;

const items = $items();

// Ordena la lista de resultados basándose en el 'video_index' que creamos al principio
items.sort((a, b) => a.json.video_index - b.json.video_index);

// Ahora la variable 'items' contiene los resultados en el orden correcto [1, 2, 3, 4]
return items;
